import dataclasses
from typing import Any, Annotated, Union
import inspect
from collections.abc import Coroutine, Mapping, Sequence
from dataclasses import dataclass
from typing_extensions import Literal, get_args, get_origin

# Mocking some fastapi/starlette things to make it runnable
class Request: pass
class Response: pass
class WebSocket: pass
class HTTPConnection: pass
class StarletteBackgroundTasks: pass
class SecurityScopes: pass

class Depends:
    def __init__(self, dependency=None):
        self.dependency = dependency

class FieldInfo:
    def __init__(self, default=None):
        self.default = default

class ParamDetails:
    def __init__(self, type_annotation, depends, field):
        self.type_annotation = type_annotation
        self.depends = depends
        self.field = field
    def __repr__(self):
        return f"ParamDetails(type_annotation={self.type_annotation}, depends={self.depends}, field={self.field})"

def lenient_issubclass(cls, base):
    if cls is Any: return False
    try:
        return issubclass(cls, base)
    except TypeError:
        return False

def analyze_param(param_name, annotation, value, is_path_param):
    field_info = None
    depends = None
    type_annotation = Any
    use_annotation = Any
    if annotation is not inspect.Signature.empty:
        use_annotation = annotation
        type_annotation = annotation

    if get_origin(use_annotation) is Annotated:
        annotated_args = get_args(annotation)
        type_annotation = annotated_args[0]
        fastapi_annotations = [arg for arg in annotated_args[1:] if isinstance(arg, (FieldInfo, Depends))]
        if fastapi_annotations:
            fastapi_annotation = fastapi_annotations[-1]
        else:
            fastapi_annotation = None

        if isinstance(fastapi_annotation, FieldInfo):
            field_info = fastapi_annotation
        elif isinstance(fastapi_annotation, Depends):
            depends = fastapi_annotation

    if isinstance(value, Depends):
        depends = value
    elif isinstance(value, FieldInfo):
        field_info = value

    if depends is not None and depends.dependency is None:
        depends = dataclasses.replace(depends, dependency=type_annotation)

    # --- THE CHANGE ---
    if depends is None and lenient_issubclass(
        type_annotation,
        (
            Request,
            WebSocket,
            HTTPConnection,
            Response,
            StarletteBackgroundTasks,
            SecurityScopes,
        ),
    ):
        assert field_info is None, (
            f"Cannot specify FastAPI annotation for type {type_annotation!r}"
        )
    # --- END CHANGE ---
    elif field_info is None and depends is None:
        # Simplified for the test
        field = "Body/Query/etc" if not lenient_issubclass(type_annotation, (Request, Response)) else None
    else:
        field = None

    return ParamDetails(type_annotation=type_annotation, depends=depends, field=field)

# Test Case 1: Response with Depends
def modify_response(): return Response()
try:
    res = analyze_param('response', Response, Depends(modify_response), False)
    print(f'Case 1 success: {res}')
except Exception as e:
    print(f'Case 1 failed: {e}')

# Test Case 2: Response without Depends
try:
    res = analyze_param('response', Response, inspect.Signature.empty, False)
    print(f'Case 2 success: {res}')
except Exception as e:
    print(f'Case 2 failed: {e}')

# Test Case 3: Request with Depends
def modify_request(): return Request()
try:
    res = analyze_param('request', Request, Depends(modify_request), False)
    print(f'Case 3 success: {res}')
except Exception as e:
    print(f'Case 3 failed: {e}')
